 async function refresh(){try{const r=await fetch('/api/platform'+(currentSelected.current?'?order='+currentSelected.current:''));if(r.status===401){setData(null);return;}const j:any=await r.json();if(!r.ok)throw new Error(j.error);setData(j);setRates(normalizeRates(j.rates));if(ready.current&&'Notification' in window&&Notification.permission==='granted'){for(const n of j.notifications||[])if(!n.read&&!seen.current.has(n.id)){const notification=new Notification('Black and White',{body:n.text,tag:n.id});notification.onclick=()=>{window.focus();if(n.order_id){setSelected(n.order_id);setView('detail');}};}}for(const n of j.notifications||[])seen.current.add(n.id);ready.current=true;}catch(e:any){setError(e.message);}finally{setAuthLoading(false);}}
 useEffect(()=>{fetch('/api/platform?public=1').then(r=>r.json()).then((j:any)=>{if(j.rates)setRates(normalizeRates(j.rates));if(j.reviews)setPublicReviews(j.reviews)}).catch(()=>{});refresh();const timer=setInterval(refresh,15000);const hash=location.hash.slice(1);if(['book','orders','work','crm','rates','people','launch','calendar'].includes(hash))setView(hash);try{const saved=sessionStorage.getItem('bw-booking');if(saved){const parsed=JSON.parse(saved);if(quoteSchema.safeParse(parsed).success)setDraft({...initial,...parsed})}}catch{}
 try{const encoded=new URLSearchParams(location.search).get('quote');if(encoded&&encoded.length<=6000){const shared=JSON.parse(encoded),checked=quoteSchema.safeParse(shared.input);if(checked.success){setDraft((v:any)=>({...v,...checked.data,...(/^\d{4}-\d{2}-\d{2}$/.test(shared.date||'')?{date:shared.date}:{}),...(/^(0[8-9]|1\d|20):[03]0$/.test(shared.time||'')?{time:shared.time}:{}),liveConsent:false,terms:false}));setBookingStep(0);setView('book');history.replaceState(null,'',location.pathname+'#book')}}}catch{}
 return()=>clearInterval(timer)},[]);
 useEffect(()=>{try{const saved=localStorage.getItem('bw-cookie-consent');if(saved==='all'||saved==='necessary'){setCookieConsent(saved);setCookieAnalytics(saved==='all')}}catch{}setCookieReady(true)},[]);
