 {(isAdmin||order.crew.includes(user.id))&&['assigned','en_route','in_progress'].includes(order.status)&&<button className="btn accent full" disabled={busy} onClick={()=>act('status',{id:order.id,status:order.status==='assigned'?'en_route':order.status==='en_route'?'in_progress':'review'},'Статус заказа обновлён')}>{order.status==='assigned'?'Выехали к клиенту':order.status==='en_route'?'Начать уборку':'Передать на приёмку'}<ArrowRight size={17}/></button>}
