function Rates({rates,busy,save}:{rates:any,busy:boolean,save:(r:any)=>void}){const [r,setR]=useState<any>(structuredClone(rates));const [example,setExample]=useState<QuoteInput>({...initial,area:60});const q=calculate(example,r);const num=(value:any)=>Math.max(0,Number(value)||0);return <><div className="page-title"><div><span className="eyebrow">ПРОЗРАЧНАЯ МАТЕМАТИКА</span><h1>Цена, в которой всё сходится.</h1><p>Прайсы Москвы проверены 18 октября 2026. Коэффициенты — настройки Black and White, а не средние рынка.</p></div><button className="btn" disabled={busy} onClick={()=>save(r)}>Сохранить тарифы <Check size={17}/></button></div><div className="panel"><h2>Базовые тарифы</h2><div className="table-scroll"><table><thead><tr><th>Уборка</th><th>₽ / м²</th><th>Минимум, ₽</th><th>м² / чел.-час</th></tr></thead><tbody>{Object.entries(services).filter(([k])=>k!=='custom').map(([k,s])=><tr key={k}><td><strong>{s.name}</strong></td>{['rate','min','speed'].map(f=><td key={f}><input aria-label={s.name+' '+f} type="number" min={f==='speed'?1:0} value={r.services[k][f]} onChange={e=>setR({...r,services:{...r.services,[k]:{...r.services[k],[f]:Math.max(f==='speed'?1:0,num(e.target.value))}}})}/></td>)}</tr>)}</tbody></table></div><p className="footnote">Нормативы производительности — стартовые гипотезы. Корректируйте после первых 20–30 объектов. Число клинеров не умножает цену: оно влияет на длительность.</p></div><div className="two-columns"><div className="panel"><h2>Коэффициенты и опции</h2>{[['dirt',0,'Обычное загрязнение'],['dirt',1,'Сильное загрязнение'],['dirt',2,'Очень сильное загрязнение'],['frequency',1,'Раз в две недели'],['frequency',2,'Еженедельно']].map(([key,i,label]:any)=><label className="rate-row" key={key+i}><span>{label}</span><input type="number" min={key==='dirt'?1:.5} max={key==='dirt'?3:1} step="0.05" value={r[key][i]} onChange={e=>{const list=[...r[key]];list[i]=num(e.target.value);setR({...r,[key]:list})}}/></label>)}<label className="rate-row"><span>Срочная уборка</span><input type="number" min="1" max="3" step=".05" value={r.urgent} onChange={e=>setR({...r,urgent:num(e.target.value)})}/></label>{Object.entries(extras).map(([k,e])=><label className="rate-row" key={k}><span>{e.name}, ₽</span><input type="number" min="0" value={r.extras[k].price} onChange={e=>setR({...r,extras:{...r.extras,[k]:{...r.extras[k],price:num(e.target.value)}}})}/></label>)}</div><div className="panel"><h2>Плановые расходы</h2>{[['hourlyPay','Выплата, ₽ / чел.-час'],['transport','Транспорт, ₽ / сотрудник'],['videoPerPerson','Видео, резерв ₽ / сотрудник'],['suppliesPercent','Материалы, % выручки'],['overheadPercent','Операционные расходы, %'],['taxReservePercent','Налоговый резерв, %']].map(([key,label])=><label className="rate-row" key={key}><span>{label}</span><input type="number" min="0" value={r[key]} onChange={e=>setR({...r,[key]:num(e.target.value)})}/></label>)}<p className="footnote">Резерв на налоги — допущение модели, а не определение налогового режима. Эквайринг, маркетинг, переделки и постоянные затраты уточняются по факту.</p><div className="calculator-example"><h3>Проверить экономику</h3><div className="field-row"><label className="field">Уборка<select value={example.service} onChange={e=>setExample({...example,service:e.target.value as any})}>{Object.entries(services).filter(([k])=>k!=='custom').map(([k,s])=><option key={k} value={k}>{s.name}</option>)}</select></label><label className="field">м²<input type="number" min="15" max="10000" value={example.area} onChange={e=>setExample({...example,area:Math.max(15,Math.min(10000,num(e.target.value)))})}/></label></div><div className="quote-lines"><div><span>Цена клиенту</span><b>{money(q.total)}</b></div><div><span>Трудоёмкость</span><b>{q.personHours} чел.-ч</b></div><div><span>Команда и время</span><b>{q.workers} чел. × ≈ {q.hours} ч</b></div><div><span>Плановые расходы</span><b>{money(q.cost)}</b></div><div><span>Расчётный остаток</span><b>{money(q.contribution)} · {q.margin}%</b></div></div>{q.margin<15&&<p className="warning">Низкий расчётный остаток. Проверьте тариф и расходы перед запуском.</p>}</div></div></div><div className="panel"><h2>Откуда взялись ориентиры</h2><p>Это выборка опубликованных цен «от». Разный состав услуг и минимумы не позволяют честно называть их средней ценой рынка.</p><div className="table-scroll"><table><thead><tr><th>Источник</th><th>Опубликованный ориентир</th><th>Единица</th></tr></thead><tbody><tr><td><a href="https://qlean.ru/cleaning/standard" target="_blank" rel="noreferrer">Qlean ↗</a></td><td>3 090 / 3 690 / 4 190 ₽</td><td>1 / 2 / 3 комнаты, 1 санузел</td></tr><tr><td><a href="https://cleanon.ru/price/" target="_blank" rel="noreferrer">CleanOn ↗</a></td><td>80 / 180 / 200 ₽</td><td>м²: поддерживающая / генеральная / после ремонта</td></tr><tr><td><a href="https://www.domovenok.ru/price" target="_blank" rel="noreferrer">Домовёнок ↗</a></td><td>3 900 / 15 640 / 12 960 ₽</td><td>До 50 м²: те же типы уборки</td></tr></tbody></table></div><div className="formula">Цена = округление вверх до 100 ₽ [ max(минимум, м² × ставка) × загрязнение × регулярность × срочность + опции ]</div></div></>}
function Launch(){return <><div className="page-title"><div><span className="eyebrow">ОТ ПИЛОТА К РЕАЛЬНОЙ КОМПАНИИ</span><h1>Честно о готовности.</h1><p>Рабочая система требует не только сайта, но и подключённой команды, связи и операционных правил.</p></div></div><div className="two-columns"><div className="panel"><h2>Уже в системе</h2>{['Серверная база заказов, сотрудников и команд','Авторизация и проверка прав на сервере','Калькулятор и редактируемые тарифы','Предложения, принятие и проверка занятости','CRM, расписание и журнал изменений','Чек-лист, приватные фото и чат','Уведомления внутри сайта и при открытой вкладке','WebRTC: камера телефона и просмотр клиентом','Пауза, отзыв согласия, завершение доступа'].map(s=><div className="launch-item" key={s}><CheckCircle2 size={19}/><span>{s}</span></div>)}</div><div className="panel"><h2>До первого реального заказа</h2>{[['Команда','Добавить сотрудников, назначить бригадира, дать доступ к закрытому сайту и провести тестовый заказ.'],['Связь между мобильными сетями','Подключить TURN-сервер и проверить эфир на двух телефонах в разных сетях. Входящие параметры: TURN_URLS, TURN_USERNAME, TURN_CREDENTIAL.'],['Инфраструктура для России','Проверить размещение БД и медиасервера, локализацию и обработку персональных данных. Sites сейчас используется для закрытого пилота с тестовыми сведениями.'],['Юридические и операционные документы','Реквизиты оператора, оферта, политика данных, согласия на видео, правила отмены, переделок и работы с ключами.'],['Оплата','Заглушка по заданию. Подключить провайдера, чеки, возвраты и webhook перед приёмом онлайн-платежей.'],['Фоновые уведомления','Сейчас сайт должен быть открыт. Подключить Web Push / SMS / Telegram с согласиями и доставкой через очередь.']].map(([t,d])=><div className="launch-item pending" key={t}><AlertCircle size={19}/><span><b>{t}</b><small>{d}</small></span></div>)}</div></div><div className="panel"><h2>Пилотный день: пройти весь путь</h2><div className="how-grid compact">{[['1','Клиент создаёт заявку','Выбрать услугу, время, тестовый адрес и согласие на видео.'],['2','Диспетчер предлагает заказ','Назначить команду достаточного размера. Бригадир принимает.'],['3','Команда выполняет','Выезд → начало → камера → чек-лист → фото → приёмка.'],['4','Клиент подтверждает','Проверить эфир, отправить сообщение и принять результат.']].map(([n,t,d])=><div key={n}><span>{n}</span><h3>{t}</h3><p>{d}</p></div>)}</div><p className="footnote">Для проверки разграничения доступа нужны отдельные аккаунты клиента и сотрудника. Администратор не получает право просмотра чужих эфиров автоматически.</p></div></>}
